def letterize(num):
    return chr(num + ord('A')))

def numify(letter):
    return ord(letter) - ord('A'))

def cipher(text, shift):
    result = ""

    for letter in text:
        if letter.isalpha():
            num = numify(letter)
            num = (num + shift) % 26
            result += letterize(num)
        else:
            result += letter

    return result
